import { createStep, createWorkflow } from "@mastra/core/workflows";
import {
  HistorianPolicyError,
  validateHistorianStatement,
  type HistorianToolResult,
  type SqlReview,
} from "@packt-workshop/contracts";
import {
  generatedSqlSchema,
  queryHistorianInputSchema,
  queryHistorianOutputSchema,
  reviewedSqlSchema,
  type ReviewedSql,
} from "./schemas";
import {
  createSqlGenerationFunction,
  createSqlGeneratorAgent,
  type SqlGenerationFunction,
} from "./agents/sql-generator-agent";
import {
  createJevSqlReviewFunction,
  type SqlReviewFunction,
} from "./agents/jev-sql-reviewer";

const POLICY_VERSION = "historian-v1";

export function createHistorianQueryWorkflow(
  apiKey: string,
  model: string,
  facilityBaseUrl: string,
  dependencies: {
    generateSql?: SqlGenerationFunction;
    reviewSql?: SqlReviewFunction;
    request?: typeof globalThis.fetch;
  } = {},
) {
  const request = dependencies.request ?? globalThis.fetch;
  const generateSqlProposal =
    dependencies.generateSql ??
    createSqlGenerationFunction(createSqlGeneratorAgent(apiKey, model));
  const reviewSqlProposal =
    dependencies.reviewSql ?? createJevSqlReviewFunction(apiKey);

  return createWorkflow({
    id: "historian-query",
    description:
      "Call once with the operator's complete historian question. Generate one SQL proposal, preflight its statement policy, review its meaning and fixed-grid result shape, then deterministically validate and execute it against the read-only facility historian.",
    inputSchema: queryHistorianInputSchema,
    outputSchema: queryHistorianOutputSchema,
  })
    .then(createGenerateSqlStep(generateSqlProposal))
    .then(createDeterministicSqlCheck())
    .then(createAgenticSqlCheck(reviewSqlProposal))
    .then(createValidateAndExecuteStep(facilityBaseUrl, request))
    .commit();
}

function createGenerateSqlStep(generateSqlProposal: SqlGenerationFunction) {
  return createStep({
    id: "generate-sql",
    description:
      "Use the dedicated SQL generator agent to turn the operator question into one structured SQLite proposal.",
    inputSchema: queryHistorianInputSchema,
    outputSchema: generatedSqlSchema,
    execute: async ({ inputData }) => ({
      question: inputData.question,
      ...(await generateSqlProposal(inputData.question)),
    }),
  });
}

function createDeterministicSqlCheck() {
  return createStep({
    id: "preflight-sql",
    description:
      "Deterministically reject write operations and multiple statements before calling the SQL reviewer. This is an early check, not execution authorization.",
    inputSchema: generatedSqlSchema,
    outputSchema: generatedSqlSchema,
    execute: async ({ inputData, bail }) => {
      try {
        validateHistorianStatement(inputData.sql);
        // Review and execute the exact proposal; do not rewrite it here.
        return inputData;
      } catch (error) {
        if (!(error instanceof HistorianPolicyError)) throw error;
        return bail<HistorianToolResult>({
          ...inputData,
          status: "rejected",
          stage: "preflight",
          code: error.code,
          message: `SQL preflight rejected the proposal: ${error.message}`,
          review: {
            approved: false,
            concerns: [],
          },
          policyVersion: POLICY_VERSION,
        });
      }
    },
  });
}

function createAgenticSqlCheck(reviewSqlProposal: SqlReviewFunction) {
  return createStep({
    id: "review-sql",
    description:
      "Ask Jev about query safety, human intent, and stored reading columns.",
    inputSchema: generatedSqlSchema,
    outputSchema: reviewedSqlSchema,
    execute: async ({ inputData }) => {
      let review: SqlReview;
      try {
        review = await reviewSqlProposal(inputData);
      } catch (error) {
        review = {
          approved: false,
          concerns: [
            error instanceof Error ? error.message : "Unknown review error.",
          ],
        };
      }
      return { ...inputData, review };
    },
  });
}

function createValidateAndExecuteStep(
  facilityBaseUrl: string,
  request: typeof globalThis.fetch,
) {
  return createStep({
    id: "deterministic-validate-and-execute",
    description:
      "Apply the reviewer decision, then ask the facility-owned deterministic policy to validate and execute the exact SQL atomically.",
    inputSchema: reviewedSqlSchema,
    outputSchema: queryHistorianOutputSchema,
    execute: async ({ inputData, abortSignal }) => {
      if (!inputData.review.approved) return reviewerRejection(inputData);

      const response = await request(`${facilityBaseUrl}/api/historian/query`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(inputData),
        ...(abortSignal ? { signal: abortSignal } : {}),
      });
      if (!response.ok) {
        throw new Error(
          `Historian service rejected the request with HTTP ${response.status}.`,
        );
      }
      return queryHistorianOutputSchema.parse(await response.json());
    },
  });
}

const reviewerRejection = (input: ReviewedSql): HistorianToolResult => ({
  status: "rejected",
  stage: "reviewer",
  code: "REVIEW_REJECTED",
  message:
    "The historian query was not executed because the reviewer rejected it.",
  ...input,
  policyVersion: POLICY_VERSION,
});

import { createOpenAI } from "@ai-sdk/openai";
import { Agent } from "@mastra/core/agent";
import { z } from "zod";

export const SQL_GENERATOR_INSTRUCTIONS = `Generate one read-only SQLite SELECT or WITH query and a short explanation.

View: historian_readings
Always return all these output columns: reading_id, recorded_at, room_id, room_name, metric_id, metric_name, unit, numeric_value, text_value, shift_manager_name, condition.
recorded_at is ISO-8601 UTC. condition is normal, warning, critical, or unavailable.
Rooms: Cooling room, Packaging hall.
Metrics: Air temperature, Relative humidity, Product surface temperature, Supply-air temperature, Cooling-unit power, Line state, Line speed, Seal temperature, Package reject rate.
Use exact catalog values. Unqualified "temperature" means Air temperature.

For highest/lowest reading requests, select the complete stored row, retaining its timestamp, room, metric, and condition. Per group, use ROW_NUMBER; break ties by latest recorded_at, then reading_id. Exclude the ranking column from the final output.
MAX, MIN, and AVG are supported as numeric_value. For aggregate results, return every column; retain metadata that has one value within the group, otherwise return NULL under that column's name. Never select ungrouped, non-aggregated metadata alongside an aggregate. Do not invent output columns.
Example for average air temperature per shift manager:
SELECT NULL AS reading_id, NULL AS recorded_at, NULL AS room_id, NULL AS room_name, NULL AS metric_id, metric_name, unit, AVG(numeric_value) AS numeric_value, NULL AS text_value, shift_manager_name, NULL AS condition FROM historian_readings WHERE metric_name = 'Air temperature' GROUP BY shift_manager_name, metric_name, unit.`;

const sqlGenerationSchema = z
  .object({
    sql: z.string().trim().min(1).max(12_000),
    explanation: z.string().trim().min(1).max(1_000),
  })
  .strict();

export type SqlGeneration = z.infer<typeof sqlGenerationSchema>;
export type SqlGenerationFunction = (
  question: string,
) => Promise<SqlGeneration>;

export const createSqlGeneratorAgent = (apiKey: string, model: string) => {
  const openrouter = createOpenAI({
    apiKey,
    baseURL: "https://openrouter.ai/api/v1",
  });

  return new Agent({
    id: "sql-generator",
    name: "Historian SQL Generator",
    description:
      "Turns one facility historian question into a structured read-only SQLite query proposal.",
    instructions: SQL_GENERATOR_INSTRUCTIONS,
    model: openrouter(model),
  });
};

export function createSqlGenerationFunction(
  generator: ReturnType<typeof createSqlGeneratorAgent>,
): SqlGenerationFunction {
  return async (question) => {
    const result = await generator.generate(`Operator question:\n${question}`, {
      abortSignal: AbortSignal.timeout(30_000),
      maxSteps: 1,
      modelSettings: { temperature: 0, maxOutputTokens: 1_500 },
      structuredOutput: {
        schema: sqlGenerationSchema,
        jsonPromptInjection: "auto",
      },
    });
    return sqlGenerationSchema.parse(result.object);
  };
}

